std::vector<int> v(5);
size_t invalid_idx = v.size(); // 5

// STL Precondition: index < v.size()
// operator[] provides zero overhead performance.
// The compiler assumes the index is safe.

// Undefined Behavior (UB):
// Violates vector access precondition.
int garbage = v[invalid_idx];

// Contrast (Safe, but has runtime overhead check):
// try { v.at(invalid_idx); } catch (...) { /* ... */ }

// The optimizer relies on preconditions being met.
// If violated, execution path is unpredictable (UB).
